import re

def parse_duration(text):
    if not isinstance(text, str) or not text:
        return None

    # Handle pure digits (interpreted as seconds)
    if text.isdigit():
        return int(text)

    # Find all number-unit pairs (e.g., "1h", "30m", "20s")
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, text)

    if not matches:
        return None

    # Verify the entire string is accounted for by the matches
    reconstructed = ''.join(f"{num}{unit}" for num, unit in matches)
    if reconstructed != text:
        return None

    # Verify units appear in order: hours before minutes before seconds
    units = [unit for _, unit in matches]
    unit_order = {'h': 0, 'm': 1, 's': 2}

    for i in range(len(units) - 1):
